let importSession=null,importGeneration=0;
const importSamples=[['A001','课堂记事本','课堂记录','普通白名单商品','book','标准款',19,20,'是'],['A001','课堂记事本','课堂记录','普通白名单商品','book','加厚款',25,10,'否'],['A002','随身布包','日常收纳','普通白名单商品','','标准款',26,12,'是'],['B001','测试问题商品','测试组内错误','普通白名单商品','cup','标准款',20,5,'是'],['B001','测试问题商品','测试组内错误','普通白名单商品','cup','大号',-5,2,'否'],['C001','专项示例商品','类目拦截演示','专项许可类目','box','标准款',30,4,'是']];
function importWorkbook(rows){const w=XLSX.utils.book_new();const sheet=XLSX.utils.aoa_to_sheet([ImportModel.headers,...rows]);sheet['!cols']=[18,24,32,24,16,22,12,12,14].map(wch=>({wch}));XLSX.utils.book_append_sheet(w,sheet,'商品导入');const notes=[['填写说明','内容'],['行规则','每行一个规格，同组编号表示同一商品；编号仅在本文件生效'],['同组信息','商品名称、介绍、类目和图片编号必须一致；恰好一个默认规格填是'],['准入类目','仅填写普通白名单商品'],['图片编号','可整组留空导入草稿；上架前须选择有效预置图片'],['数值规则','价格大于0，最多两位小数；库存为非负整数'],['处理规则','组内任一行错误则整组不导入；有效组生成草稿'],['填写方式','请直接填写值，不使用公式；第一行列名保持不变'],[],['图片编号','预置图片名称'],...Object.entries(presetNames)];const guide=XLSX.utils.aoa_to_sheet(notes);guide['!cols']=[{wch:20},{wch:90}];XLSX.utils.book_append_sheet(w,guide,'填写说明');return w;}
function downloadImportTemplate(){XLSX.writeFile(importWorkbook([]),'商品导入模板.xlsx');}
function showImportStart(){++importGeneration;importSession=null;modal('Excel 批量导入',`<div class="importHero"><span class="tag">仅限普通白名单商品</span><h2>一次整理，批量创建商品草稿</h2><p>选择 Excel → 校验预览 → 确认导入 → 完善草稿</p></div><div class="importStartActions"><button id="downloadImportTemplate">下载 Excel 模板</button><button id="downloadImportExample">下载演示文件</button></div><label class="reportField">选择 Excel 文件<input id="excelFile" type="file" accept=".xlsx,.xls"></label><p class="muted">读取“商品导入”工作表，保留原始行号；Excel 文件在本机解析。当前 Demo 模拟服务端校验与写入。</p><p id="importReadError" role="alert"></p><div class="orderActions"><button id="importExit">返回商品管理</button><button id="loadImportExample" class="primary">直接体验示例校验</button></div>`);$('downloadImportTemplate').onclick=downloadImportTemplate;$('downloadImportExample').onclick=()=>XLSX.writeFile(importWorkbook(importSamples),'商品导入演示.xlsx');$('importExit').onclick=()=>{$('dialog').close();openSeller('products');};$('loadImportExample').onclick=()=>prepareImport(importSamples,'内置演示文件');$('excelFile').onchange=async e=>{const file=e.target.files[0],token=++importGeneration;if(!file)return;const target=$('importReadError');target.textContent='正在解析…';try{const bytes=await file.arrayBuffer();if(token!==importGeneration||!target.isConnected)return;const book=XLSX.read(bytes,{type:'array'}),sheet=book.Sheets['商品导入'];if(!sheet)throw Error('缺少“商品导入”工作表，请使用模板');for(const [key,cell] of Object.entries(sheet))if(!key.startsWith('!')&&cell.f)throw Error('单元格 '+key+' 含公式，请替换为实际值');const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',blankrows:true,raw:true,range:0});if(!ImportModel.headers.every((h,i)=>matrix[0]?.[i]===h))throw Error('第一行列名不匹配，请使用下载的模板');prepareImport(matrix.slice(1),file.name);}catch(err){if(target.isConnected)target.textContent='解析失败：'+err.message;}};}
function prepareImport(data,name){++importGeneration;const result=ImportModel.validate(data,[...createdProducts,...products.filter(p=>p.shop===0)]);importSession={data:structuredClone(data),name,result,done:false,cancelled:false,id:'IMP'+Date.now()};showImportPreview();}
function importReport(){const s=importSession;if(!s)return;const bad=s.result.rows.filter(r=>r.status!=='待导入'||r.warning);const data=[['Excel行号',...ImportModel.headers,'校验状态','错误原因','提示'],...bad.map(r=>[r.line,...r.values,r.status,r.errors.join('；'),r.warning])];const w=XLSX.utils.book_new(),sheet=XLSX.utils.aoa_to_sheet(data);sheet['!cols']=data[0].map((_,i)=>({wch:i>=10?50:20}));XLSX.utils.book_append_sheet(w,sheet,'校验报告');XLSX.writeFile(w,'商品导入校验报告.xlsx');}
function showImportPreview(){const s=importSession,r=s.result,good=r.rows.filter(x=>x.status==='待导入').length;modal('导入校验预览',`<p>${escapeHTML(s.name)}</p><div class="importStats"><div><b>${r.rows.length}</b><span>规格行</span></div><div><b>${r.totalGroups}</b><span>商品组</span></div><div><b>${r.valid.length}</b><span>可导入商品</span></div><div><b>${r.rows.length-good}</b><span>不导入行（含同组受影响）</span></div></div><p class="muted">当前尚未写入商品。错误商品组整体跳过，同名提示不影响导入。</p><div class="importTableWrap"><table class="importTable"><thead><tr><th>原行号</th><th>分组 / 商品</th><th>规格</th><th>价格 / 库存</th><th>默认 / 图片</th><th>状态与说明</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.line}</td><td>${escapeHTML(x.values[0])}<br><b>${escapeHTML(x.values[1])}</b><small>${escapeHTML(x.values[2])}<br>${escapeHTML(x.values[3])}</small></td><td>${escapeHTML(x.values[5])}</td><td>${escapeHTML(x.values[6])}<br>库存 ${escapeHTML(x.values[7])}</td><td>${escapeHTML(x.values[8])}<br>${escapeHTML(x.values[4]||'待补图')}</td><td class="${x.status==='待导入'?'':'importBad'}"><b>${x.status}</b><p>${escapeHTML(x.errors.join('；'))}</p><p class="importWarning">${escapeHTML(x.warning)}</p></td></tr>`).join('')||'<tr><td colspan="6">文件没有商品数据，请返回填写模板。</td></tr>'}</tbody></table></div><div class="editorFooter"><button id="cancelImport">取消导入</button><div><button id="downloadImportReport">下载校验报告</button><button id="confirmImport" class="primary" ${r.valid.length?'':'disabled'}>导入 ${r.valid.length} 个有效商品</button></div></div>`);$('dialog').classList.add('importDialog');$('downloadImportReport').onclick=importReport;$('cancelImport').onclick=()=>{s.cancelled=true;modal('已取消导入','<h2>未创建任何商品</h2><p>可以下载校验报告，修改 Excel 后重新选择文件。</p><div class="orderActions"><button id="cancelledReport">下载校验报告</button><button id="restartImport">重新选择文件</button></div>');$('cancelledReport').onclick=importReport;$('restartImport').onclick=showImportStart;};$('confirmImport').onclick=()=>{if(s.done||s.cancelled)return;const recheck=ImportModel.validate(s.data,[...createdProducts,...products.filter(p=>p.shop===0)]);s.result=recheck;if(!recheck.valid.length){showImportPreview();return;}const batch=recheck.valid.map((item,i)=>({...item,id:s.id+'-'+i}));createdProducts.push(...batch);s.done=true;modal('导入完成',`<span class="tag">已保存为草稿</span><h2>成功导入 ${batch.length} 个商品</h2><p>共 ${batch.reduce((n,p)=>n+p.variants.length,0)} 个规格。可以在商品管理中编辑，并为缺少图片的草稿选择预置图片后上架。</p><div class="orderActions"><button id="finishedReport">下载校验报告</button><button class="primary" id="viewImportedDrafts">前往商品草稿</button></div>`);$('finishedReport').onclick=importReport;$('viewImportedDrafts').onclick=()=>{$('dialog').close();openSeller('products');const b=sellerReviewPage.querySelector('[data-managed-filter="草稿"]');b?.click();};};}
const importModalBase=modal;modal=function(title,html){$('dialog').classList.remove('importDialog');importModalBase(title,html);};const importDetailBase=sellerDetail;sellerDetail=function(kind){if(kind==='import')showImportStart();else importDetailBase(kind);};
